function rebaseAsset(value){if(typeof value!=='string')return value;try{let u=new URL(value,PortableAssetBase),key=u.pathname;if(u.pathname==='/_next/image'){const src=u.searchParams.get('url');if(src)key=new URL(src,PortableAssetBase).pathname}const matched=assetKeys.find(asset=>key===asset||key.endsWith(asset));return matched?new URL(matched.replace(/^\//,''),PortableAssetBase).href:value}catch{return value}}
function adapt(node){if(Array.isArray(node))return node.map(adapt);if(!React.isValidElement(node))return node;const p={...node.props};if(typeof p.src==='string')p.src=rebaseAsset(p.src);if(typeof p.srcSet==='string')p.srcSet=p.srcSet.split(',').map(x=>{const [url,...rest]=x.trim().split(/\s+/);return [rebaseAsset(url),...rest].join(' ')}).join(', ');if(p.style&&typeof p.style.backgroundImage==='string')p.style={...p.style,backgroundImage:p.style.backgroundImage.replace(/url\(([^)]+)\)/g,(m,u)=>'url("'+rebaseAsset(u.replace(/^['"]|['"]$/g,''))+'")')};if('children'in p)p.children=adapt(p.children);return React.cloneElement(node,p)}
